-- H2 Database Schema for EPMICMPCOD-300: View Task List
-- This schema is automatically generated by Hibernate via ddl-auto=create-drop
-- This file is for reference and documentation purposes only.

-- Create tasks table
CREATE TABLE IF NOT EXISTS tasks (
    id UUID PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    user_id VARCHAR(50) NOT NULL,
    status VARCHAR(50) DEFAULT 'PENDING' NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Create performance indexes
CREATE INDEX IF NOT EXISTS idx_tasks_user_id ON tasks(user_id);
CREATE INDEX IF NOT EXISTS idx_tasks_user_status ON tasks(user_id, status);

-- Add comments for documentation
COMMENT ON TABLE tasks IS 'Table storing task records for users';
COMMENT ON COLUMN tasks.id IS 'Unique task identifier (UUID)';
COMMENT ON COLUMN tasks.title IS 'Task title (required)';
COMMENT ON COLUMN tasks.description IS 'Detailed task description (optional)';
COMMENT ON COLUMN tasks.user_id IS 'User who owns this task';
COMMENT ON COLUMN tasks.status IS 'Task status: PENDING, IN_PROGRESS, or COMPLETED';
COMMENT ON COLUMN tasks.created_at IS 'Timestamp when task was created';
COMMENT ON COLUMN tasks.updated_at IS 'Timestamp when task was last updated';
